import{_ as s,a,c as t,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第四册：流利英语 · 单元 2 复习与自测","description":"L9–L16 原创练习和答案解析。","frontmatter":{"title":"第四册：流利英语 · 单元 2 复习与自测","description":"L9–L16 原创练习和答案解析。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","summary":"L9–L16 原创练习和答案解析。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · 单元 2 单词与短语","link":"/life/english/new-concept/book-4/unit-02/vocabulary"},"next":{"text":"第四册：流利英语 · 单元 3：证据、解释与表达焦点","link":"/life/english/new-concept/book-4/unit-03/overview"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · 单元 2 单词与短语","link":"/life/english/new-concept/book-4/unit-02/vocabulary"},"next":{"text":"第四册：流利英语 · 单元 3：证据、解释与表达焦点","link":"/life/english/new-concept/book-4/unit-03/overview"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-02/review.md","filePath":"life/english/new-concept/book-4/unit-02/review.md"}'),r={name:"life/english/new-concept/book-4/unit-02/review.md"};function n(i,e,l,h,c,p){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="第四册-流利英语-·-单元-2-复习与自测" tabindex="-1">第四册：流利英语 · 单元 2 复习与自测 <a class="header-anchor" href="#第四册-流利英语-·-单元-2-复习与自测" aria-label="Permalink to &quot;第四册：流利英语 · 单元 2 复习与自测&quot;">​</a></h1><p><a href="/life/english/new-concept/book-4/unit-02/overview">单元导读</a> · <a href="/life/english/new-concept/book-4/unit-02/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-4/unit-02/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-4/unit-02/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-9-·-过去完成时与过去叙事参照点" tabindex="-1">Lesson 9 · 过去完成时与过去叙事参照点 <a class="header-anchor" href="#lesson-9-·-过去完成时与过去叙事参照点" aria-label="Permalink to &quot;Lesson 9 · 过去完成时与过去叙事参照点&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> By the time the messenger arrived, the clerk had hidden the letter.</p><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>示例中谁先发生：藏信还是信使到达？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 藏信。</p><p><strong>解析：</strong> had hidden 早于 arrived。</p></details><p><strong>表达迁移：</strong> 创作三句档案馆小故事：先收到一封旧信，说明它此前经历了什么，再写调查动作。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The archivist received a sealed envelope on Monday. Someone had stored it behind a cabinet for years. She compared the handwriting with an earlier letter.</p><p>过去完成时只承担前情说明，第三句回到主线的一般过去时。</p></details><p><a href="/life/english/new-concept/book-4/unit-02/lesson-009">回看本课</a></p><h2 id="lesson-10-·-比较结构与范围限定" tabindex="-1">Lesson 10 · 比较结构与范围限定 <a class="header-anchor" href="#lesson-10-·-比较结构与范围限定" aria-label="Permalink to &quot;Lesson 10 · 比较结构与范围限定&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Office rents in the new district are lower than those in the city centre.</p><h3 id="练习-1-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>示例中 those 代替什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> office rents</p><p><strong>解析：</strong> 复数代词避免重复比较对象。</p></details><p><strong>表达迁移：</strong> 比较两个虚构办公园区：租金、人才交流、适用团队各写一句。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Rents in River Park are lower than those in Hill Park. Hill Park offers more networking events. A small team may prefer River Park if keeping costs down is its priority.</p><p>每句使用具体维度，最后用 if 明确选择依赖的条件。</p></details><p><a href="/life/english/new-concept/book-4/unit-02/lesson-010">回看本课</a></p><h2 id="lesson-11-·-动名词短语作主语" tabindex="-1">Lesson 11 · 动名词短语作主语 <a class="header-anchor" href="#lesson-11-·-动名词短语作主语" aria-label="Permalink to &quot;Lesson 11 · 动名词短语作主语&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Learning the names of local plants gives Mei a reason to walk outdoors.</p><h3 id="练习-1-2" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-2" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填空：Keeping old photographs ___ enjoyable for him.（be）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> is</p><p><strong>解析：</strong> 整个动名词短语作为一个活动，接单数谓语。</p></details><p><strong>表达迁移：</strong> 为愿意尝试新爱好的退休邻居提出三句温和建议，含一个动名词主语和一个条件。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Keeping a small sketchbook can make daily walks more interesting. Start with one familiar tree. If walking is difficult, sketching from a window is another option.</p><p>can 与 if 留出个体差异，末句使建议适用于不同条件。</p></details><p><a href="/life/english/new-concept/book-4/unit-02/lesson-011">回看本课</a></p><h2 id="lesson-12-·-unless-与条件从句" tabindex="-1">Lesson 12 · unless 与条件从句 <a class="header-anchor" href="#lesson-12-·-unless-与条件从句" aria-label="Permalink to &quot;Lesson 12 · unless 与条件从句&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> In this exercise, the request will remain pending unless the customer signs the form.</p><h3 id="练习-1-3" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-3" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>将 unless the customer signs 改为 if 结构。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> if the customer does not sign</p><p><strong>解析：</strong> unless 在本句等于 if not。</p></details><p><strong>表达迁移：</strong> 为虚构服务台写三句申请说明：所需文件、缺失时的结果、咨询方式。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Please attach a copy of your identification. The request will remain pending unless the copy is included. Contact the service desk if you need help with the form.</p><p>申请条件和未满足的后果分别表达，第三句提供行动入口。</p></details><p><a href="/life/english/new-concept/book-4/unit-02/lesson-012">回看本课</a></p><h2 id="lesson-13-·-目的不定式与-so-that" tabindex="-1">Lesson 13 · 目的不定式与 so that <a class="header-anchor" href="#lesson-13-·-目的不定式与-so-that" aria-label="Permalink to &quot;Lesson 13 · 目的不定式与 so that&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The team collected rock samples so that specialists could compare the layers.</p><h3 id="练习-1-4" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-4" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>示例中收集者和比较者的称呼分别是什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> the team 和 specialists</p><p><strong>解析：</strong> 两个分句的主语分别指明角色。</p></details><p><strong>表达迁移：</strong> 用三句说明一次虚构勘测：采集什么、为何分析、下一步取决于什么。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We collected samples to compare the rock layers. The results may reveal differences in their structure. Further testing will be needed before any conclusion is drawn.</p><p>目的、可能发现、结论限制依次展开，没有把勘测等同于资源发现。</p></details><p><a href="/life/english/new-concept/book-4/unit-02/lesson-013">回看本课</a></p><h2 id="lesson-14-·-第二条件句与假设距离" tabindex="-1">Lesson 14 · 第二条件句与假设距离 <a class="header-anchor" href="#lesson-14-·-第二条件句与假设距离" aria-label="Permalink to &quot;Lesson 14 · 第二条件句与假设距离&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> If we changed the starting value slightly, the two simulations might diverge over time.</p><h3 id="练习-1-5" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-5" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>示例是在报告已经改变了数值吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不是。</p><p><strong>解析：</strong> if changed 与 might 构成假设情境。</p></details><p><strong>表达迁移：</strong> 为两个模拟结果写三句说明，提出一个变量变化假设并指出预测限制。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The two curves begin close together. If we altered one starting value, they might separate later. This example illustrates sensitivity, but it does not predict a particular storm.</p><p>把图形描述、假设实验和外推边界分别表达，避免把隐喻当成事件证明。</p></details><p><a href="/life/english/new-concept/book-4/unit-02/lesson-014">回看本课</a></p><h2 id="lesson-15-·-whether-引导名词性从句" tabindex="-1">Lesson 15 · whether 引导名词性从句 <a class="header-anchor" href="#lesson-15-·-whether-引导名词性从句" aria-label="Permalink to &quot;Lesson 15 · whether 引导名词性从句&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The team must decide whether the preliminary data can be shared with partners.</p><h3 id="练习-1-6" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-6" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填空：They discussed ___ to publish the design.（whether / if）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> whether</p><p><strong>解析：</strong> whether 可以直接接不定式，if 通常不能。</p></details><p><strong>表达迁移：</strong> 写三句团队讨论记录：待决策事项、共享的一个好处、需要核查的一个条件。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We need to decide whether to share the test data. Collaboration could help another team check our results. Before release, we should identify any confidential information.</p><p>whether to 提出选择，could 说明可能收益，before 限定发布前的检查。</p></details><p><a href="/life/english/new-concept/book-4/unit-02/lesson-015">回看本课</a></p><h2 id="lesson-16-·-so-that-与-such-that-的结果表达" tabindex="-1">Lesson 16 · so…that 与 such…that 的结果表达 <a class="header-anchor" href="#lesson-16-·-so-that-与-such-that-的结果表达" aria-label="Permalink to &quot;Lesson 16 · so…that 与 such…that 的结果表达&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The crossing was so far away that several residents asked for a nearer one.</p><h3 id="练习-1-7" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-7" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填空：It was ___ a narrow pavement that two people could not pass.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> such</p><p><strong>解析：</strong> 后面是 a narrow pavement 名词短语。</p></details><p><strong>表达迁移：</strong> 用三句描述一个街区步行问题，包含程度结果结构和一条改善建议。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The bus stop is so far from the library that some visitors drive instead. A nearer stop could make the library easier to reach. The council should also ask residents about their routes.</p><p>先给具体空间问题，再提出可能改善和信息收集，不把单一观察泛化为所有城市。</p></details><p><a href="/life/english/new-concept/book-4/unit-02/lesson-016">回看本课</a></p>',67)])])}const m=s(r,[["render",n]]);export{u as __pageData,m as default};
